package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type node struct {
	x, y, step int
}

type pq []node

func (p pq) Len() int            { return len(p) }
func (p pq) Less(i, j int) bool  { return p[i].step < p[j].step }
func (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i] }
func (p *pq) Push(x interface{}) { *p = append(*p, x.(node)) }
func (p *pq) Pop() interface{} {
	old := *p
	n := len(old)
	it := old[n-1]
	*p = old[:n-1]
	return it
}

var vis [110][110]int
var f = [4][2]int{{0, 1}, {1, 0}, {0, -1}, {-1, 0}}

func bfs(l, u, xi, yi int) int {
	q := &pq{}
	heap.Init(q)
	var e, t node
	e.x, e.y, e.step = l, u, 0
	heap.Push(q, e)
	vis[e.x][e.y] = 1
	for q.Len() > 0 {
		e = heap.Pop(q).(node)
		if e.x == xi && e.y == yi {
			return e.step
		}
		for i := 0; i < 4; i++ {
			t.x = e.x + f[i][0]
			t.y = e.y + f[i][1]
			t.step = e.step + 1
			if t.x < 0 || t.y < 0 {
				continue
			}
			if t.x >= 110 || t.y >= 110 {
				continue
			}
			if vis[t.x][t.y] != 0 {
				continue
			}
			vis[t.x][t.y] = 1
			heap.Push(q, t)
		}
	}
	return -1
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var s string
	fmt.Fscan(reader, &s)
	length := len(s)
	x, y, xx, yy := 0, 0, 0, 0
	for i := 0; i < length; i++ {
		if s[i] == 'L' {
			y--
		}
		if s[i] == 'R' {
			y++
		}
		if s[i] == 'U' {
			x--
		}
		if s[i] == 'D' {
			x++
		}
		if x < xx {
			xx = x
		}
		if y < yy {
			yy = y
		}
	}
	xx, yy = -xx, -yy
	for i := 0; i < 110; i++ {
		for j := 0; j < 110; j++ {
			vis[i][j] = 1
		}
	}
	x, y = xx, yy
	for i := 0; i < length; i++ {
		if s[i] == 'L' {
			y--
		}
		if s[i] == 'R' {
			y++
		}
		if s[i] == 'U' {
			x--
		}
		if s[i] == 'D' {
			x++
		}
		vis[x][y] = 0
	}
	ans := bfs(xx, yy, x, y)

	if ans == length {
		fmt.Fprintf(writer, "OK\n")
	} else {
		fmt.Fprintf(writer, "BUG\n")
	}
}
